from pathlib import Path
import importlib.util,types,unittest,json,contextlib
from unittest import mock
ROOT=Path('/Users/dave/.codex/worktrees/9f01/dataflowbench')
source=ROOT/'reports/releases/v0.9.2/acquisition/independent-pending-codeql-03.py'
spec=importlib.util.spec_from_file_location('codeql03_recovery_source_probe',source);c=importlib.util.module_from_spec(spec);spec.loader.exec_module(c)
class TerminalRecovery(unittest.TestCase):
 def run_fixture(self,terminal,*,bad_blob=False,recover=False):
  prefix=b'{}\n'*89;rows=[{}]*89;base_raw=b'{"schema_version":1}\n';base_sha=c.sha_bytes(base_raw)
  contract_raw=b'{"source_commit":"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa"}\n';contract=json.loads(contract_raw)
  manifest={'source_commit':'a'*40,'plan_commit':'b'*40,'base_plan_commit':'c'*40,'continuation_contract':{'path':c.CONTRACT,'sha256':c.sha_bytes(contract_raw)}};mr=json.dumps(manifest).encode();ms=c.sha_bytes(mr)
  base={'bytes_sha256':base_sha,'plan':{'source_commit':'d'*40}};successor={'bytes_sha256':'e'*64,'plan':contract}
  def read(root,path,*args):return prefix if path==c.LEDGER else base_raw if path==c.BASE_CONTRACT else mr
  names={'_check_manifest':None,'_check_prefix':None,'_tail':[],'_check_contract_delta':None,'_enrich_successor_historical_contexts':None,'_attach_verified_runtime_recovery':None,'_validate_runtime_context_registration':0,'_historical_replay_contexts':{}}
  with contextlib.ExitStack() as stack:
   stack.enter_context(mock.patch.object(c,'BASE_SHA',base_sha));stack.enter_context(mock.patch.object(c,'_read',side_effect=read));stack.enter_context(mock.patch.object(c,'_ref',return_value=contract_raw))
   stack.enter_context(mock.patch.object(c,'_git_blob',return_value=b'changed' if bad_blob else contract_raw));stack.enter_context(mock.patch.object(c,'_validated_ledger_bytes',return_value=(prefix,rows)))
   stack.enter_context(mock.patch.object(c,'load_frozen',return_value={'executor':object()}));stack.enter_context(mock.patch.object(c,'_validate_base',return_value=base));stack.enter_context(mock.patch.object(c,'_successor_context',return_value=successor));stack.enter_context(mock.patch.object(c,'_replay_completed',return_value={'synthetic':True}))
   guard=stack.enter_context(mock.patch.object(c,'_assert_source_snapshot',side_effect=RuntimeError('legitimate later Rust source differs')))
   for name,result in names.items():stack.enter_context(mock.patch.object(c,name,return_value=result))
   if recover:result=c.recover_bifrost_history(ROOT,c.MANIFEST,ms,prefix)
   else:result=c.validate(ROOT,c.MANIFEST,ms,final=True,terminal=terminal,replay=True,ledger_raw=prefix)
   return result,guard.call_count
 def test_terminal_actual_recover_does_not_require_old_live_source_tree(self):
  result,calls=self.run_fixture(True,recover=True);self.assertEqual(set(result),{'base','contexts','repaired','prefix_sha256'});self.assertEqual(calls,0)
 def test_prospective_validation_still_calls_source_gate(self):
  with self.assertRaisesRegex(RuntimeError,'later Rust'):self.run_fixture(False)
 def test_execute_always_enforces_live_source_gate_before_namespace_work(self):
  with mock.patch.object(c,'_assert_source_snapshot',side_effect=RuntimeError('execute live source guard')) as guard:
   with self.assertRaisesRegex(RuntimeError,'execute live source guard'):c.execute({'runtime_recovery_verified':True})
   guard.assert_called_once()
 def test_terminal_recovery_still_checks_committed_contract_blob(self):
  with self.assertRaisesRegex(ValueError,'registered plan commit'):self.run_fixture(True,bad_blob=True,recover=True)
if __name__=='__main__':unittest.main(verbosity=2)
